script:
$Error.Clear()
if (-not $USERNAME) { throw 'USERNAME is required' }
# Already a member? (DC: the group is domain Builtin, not a local SAM group.)
Import-Module ActiveDirectory -ErrorAction SilentlyContinue
$member = @(Get-ADGroupMember -Identity 'Remote Desktop Users' -EA SilentlyContinue |
    Where-Object { $_.SamAccountName -eq $USERNAME })
if ($member.Count -gt 0) {
    Write-Output "$USERNAME already in Remote Desktop Users; no change"
    exit 0
}
try {
    # Member server: the group lives in the local SAM.
    Add-LocalGroupMember -Group 'Remote Desktop Users' -Member $USERNAME -ErrorAction Stop
    Write-Output "$USERNAME added to local Remote Desktop Users"
} catch {
    # Domain controller: the group lives in AD Builtin.
    if (Get-Command Add-ADGroupMember -EA SilentlyContinue) {
        Add-ADGroupMember -Identity 'Remote Desktop Users' -Members $USERNAME -ErrorAction Stop
        Write-Output "$USERNAME added to domain Builtin Remote Desktop Users"
    } else {
        throw
    }
    # the caught (expected) error record would trip the rc heuristic below;
    # only the success path reaches this line.
    $Error.Clear()
}
